<div class="admin-heading"><div><span>نظرة عامة</span><h1>لوحة التحكم</h1></div></div><?php if(!$dbReady):?><div class="setup-box"><b>قاعدة البيانات لم تُربط بعد</b><p>الواجهة العامة تعمل، لكن لوحة الإدارة تحتاج إعداد بيانات MySQL في ملف <code>.env</code> ثم تنفيذ <code>database/schema.sql</code>.</p></div><?php endif; ?><div class="stat-grid"><div class="stat"><span>إجمالي العملاء</span><strong><?= number_format($stats['leads']) ?></strong></div><div class="stat"><span>عملاء جدد</span><strong><?= number_format($stats['new']) ?></strong></div><div class="stat"><span>المقالات المنشورة</span><strong><?= number_format($stats['posts']) ?></strong></div><div class="stat"><span>أحداث آخر 30 يومًا</span><strong><?= number_format($stats['events']) ?></strong></div></div><div class="admin-grid"><section class="panel"><div class="panel-head"><h2>أحدث العملاء المحتملين</h2><a href="<?= e(route_path('/admin/leads')) ?>">عرض الكل</a></div><div class="table-wrap"><table><thead><tr><th>العميل</th><th>الخدمة</th><th>المصدر</th><th>الحالة</th></tr></thead><tbody><?php foreach($recent as $l):?><tr><td><b><?= e($l['name']) ?></b><small><?= e($l['phone']) ?></small></td><td><?= e($l['service']) ?></td><td><?= e($l['utm_source'] ?: 'مباشر') ?></td><td><span class="status status-<?= e($l['status']) ?>"><?= e($l['status']) ?></span></td></tr><?php endforeach; ?><?php if(!$recent):?><tr><td colspan="4" class="empty">لا توجد بيانات بعد.</td></tr><?php endif; ?></tbody></table></div></section><section class="panel"><div class="panel-head"><h2>مصادر العملاء</h2></div><div class="source-list"><?php $max=max(array_column($sources,'total')?:[1]); foreach($sources as $s):?><div><span><?= e($s['source']) ?><b><?= (int)$s['total'] ?></b></span><i style="--w:<?= ((int)$s['total']/$max)*100 ?>%"></i></div><?php endforeach; ?><?php if(!$sources):?><p class="empty">ستظهر المصادر بعد بدء الحملات.</p><?php endif; ?></div></section></div>